    "id": "pe-pp-2023-OR-sectionc-businessenterprisesport-Q18",
    "subject": "pe",
    "chapterId": "pe-business-enterprise-sport",
    "sectionId": "pe-section-c",
    "source": "LC Physical Education Ordinary 2023 — Q18",
